SELECT o.name, o.revision, u.retailer, u.country, u.category_id,
       u.retailer_product_id, u.page_summary->>'brand' AS brand,
       u.page_summary->>'product_code' AS model, u.url
FROM lg_registry.operation_urls u
JOIN lg_registry.operations o ON o.operation_id = u.operation_id
WHERE u.operation_id = 'op-20261029-01' AND u.scenario = 'pdp'
  AND (
(u.retailer = 'coolblue' AND upper(u.retailer_product_id) IN ('968130', '976232', '981300', '981696', '981697', '985599'))
    OR (u.retailer = 'costco_ca' AND upper(u.retailer_product_id) IN ('4000323290', '4000324169', '4000324252', '4000324257', '4000324258', '4000325240', '4000326262', '4000327052', '4000327103', '4000327138', '4000327567', '4000327577', '4000327581', '4000327597', '4000327617', '4000327619', '4000327654', '4000332120', '4000332155', '4000332156', '4000332732', '4000332733', '4000332753', '4000332784', '4000332801', '4000335518', '4000335542', '4000340263', '4000340276', '4000341892', '4000345043', '4000345045', '4000345077', '4000345081', '4000345097', '4000345098', '4000345115', '4000345138', '4000345140', '4000345141', '4000347489', '4000347490', '4000347503', '4000347504', '4000347968', '4000347992', '4000348010', '4000348027', '4000348046', '4000348061', '4000348062', '4000348063', '4000348075', '4000348351', '4000348435', '4000355093', '4000371049', '4000371050', '4000371097', '4000380918', '4000384460', '4000384900', '4000406822', '4000406837', '4000413166', '4000413263', '4000413413', '4000413517', '4000421232', '4000421267', '4000424704', '4000426102', '4000435597', '4000435618', '4000435637', '4000437483', '4000438666', '4000438702', '4000438703', '4000443894', '4201007755', '4201008390', '4201008427', '4201008443', '4201023829', '4201029237', '4201029310', '4201031790', '4201045834'))
    OR (u.retailer = 'darty' AND upper(u.retailer_product_id) IN ('MC353792450', 'MC353852727', 'MC353970551'))
    OR (u.retailer = 'liverpool' AND upper(u.retailer_product_id) IN ('1100156861', '1126744613', '1126948987', '1141324931', '1179776339', '1184476734', '1193071879', '1207734558'))
    OR (u.retailer = 'mediamarkt_nl' AND upper(u.retailer_product_id) IN ('1897571', '1897574', '1897578'))
  )
ORDER BY u.retailer, u.retailer_product_id, u.url
